'use client';

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import Link from 'next/link';
import anime from 'animejs';
import {
  LayoutDashboard, ReceiptText, ShoppingCart, Package, Warehouse, Users, Truck,
  WalletCards, ChartNoAxesCombined, Megaphone, PlugZap, Settings, CircleHelp,
  Bell, ExternalLink, Search, Plus, Minus, Trash2, ChevronRight, Boxes,
  CreditCard, Banknote, QrCode, TrendingUp, ArrowUpRight, TriangleAlert,
  Wifi, WifiOff, Menu, X, RefreshCw, Tag, CircleDollarSign, CheckCircle2,
  SlidersHorizontal, ShieldCheck, Sparkles, Clock3, Store, BarChart3, LogOut, Fingerprint
} from 'lucide-react';
import ProductArt from './ProductArt';
import {beverageCatalog,type BeverageCatalogItem} from '@/lib/beverageCatalog';
import { api, dateTime, money, wsUrl } from '@/lib/api';
import { createPlatformPasskey, type PasskeyRegisterOptionsJSON } from '@/lib/webauthn';

type Product={id:number;name:string;category:string;sku?:string;barcode?:string;cost:number;price:number;stock:number;min_stock:number;storefront:number;volume_ml?:number;image_url?:string};
type Order={id:number;channel:string;payment_method:string;status:string;subtotal:number;discount:number;total:number;created_at:string;customer_id?:number};
type Dashboard={revenue:number;sales:number;ticket:number;gross_profit:number;net_result:number;units:number;stock_value:number;daily_revenue:{date:string;revenue:number}[];channels:{channel:string;orders:number;revenue:number}[];payments:{payment_method:string;orders:number;revenue:number}[];recent:Order[];low_stock:{id:number;name:string;stock:number;min_stock:number}[];top_products:{name:string;qty:number}[]};
type Finance={revenue:number;cogs:number;expenses:number;net:number;expense_items:{id:number;description:string;category:string;amount:number;created_at:string}[]};
type Reports={summary:any;product_profit:any[];stock_turnover:any[];channels:any[];payments:any[];daily:any[]};
type Integration={slug:string;name:string;status:string;last_sync?:string;note?:string};
type SettingsData={store_name:string;whatsapp:string;pix_key:string;delivery_fee:number;minimum_order:number;store_open:boolean};
type Customer={id:number;name:string;phone?:string;orders:number;spent:number;created_at:string};
type Supplier={id:number;name:string;contact?:string;phone?:string;created_at:string};
type Promotion={id:number;name:string;type:string;period:string;status:string;discount_type:string;value:number;created_at:string};

type View='dashboard'|'sales'|'pdv'|'products'|'stock'|'customers'|'suppliers'|'finance'|'reports'|'marketing'|'integrations'|'settings'|'help';
const nav:[View,string,any][]=[
  ['dashboard','Dashboard',LayoutDashboard],['sales','Vendas',ReceiptText],['pdv','Caixa / PDV',ShoppingCart],['products','Produtos',Package],['stock','Estoque',Warehouse],['customers','Clientes',Users],['suppliers','Fornecedores',Truck],['finance','Financeiro',WalletCards],['reports','Relatórios',ChartNoAxesCombined],['marketing','Marketing',Megaphone],['integrations','Integrações',PlugZap],['settings','Configurações',Settings],['help','Ajuda',CircleHelp],
];
const meta:Record<View,[string,string]>={
  dashboard:['Dashboard','Visão geral do seu negócio em tempo real'], sales:['Vendas','Todas as vendas em um único lugar'], pdv:['Caixa / PDV','Venda rápida para o balcão'], products:['Produtos','Gerencie catálogo, preços e exposição'], stock:['Estoque','Controle físico, giro e alertas'], customers:['Clientes','Relacionamento e histórico de consumo'], suppliers:['Fornecedores','Parceiros, compras e reposição'], finance:['Financeiro','Receitas, despesas e resultado'], reports:['Relatórios','Indicadores para decisões melhores'], marketing:['Marketing','Promoções e campanhas'], integrations:['Integrações','PIX, iFood, WhatsApp e vitrine'], settings:['Configurações','Empresa, loja e operação'], help:['Ajuda','Diagnóstico e trilha de auditoria']
};
const channelName=(v:string)=>({pdv:'Balcão / PDV',storefront:'Vitrine',ifood:'iFood',whatsapp:'WhatsApp'}[v]||v);
const payName=(v:string)=>({pix:'PIX',card:'Cartão',cash:'Dinheiro',ifood:'iFood',other:'Outro'}[v]||v);

function Toast({text}:{text:string}){return <div className={`toast-next ${text?'show':''}`}>{text}</div>}
function Empty({children='Nenhum registro encontrado.'}:{children?:React.ReactNode}){return <div className="empty-state"><Boxes size={28}/><p>{children}</p></div>}
function StatusBadge({status}:{status:string}){const ok=/confirm|ready|ativa|online|normal/i.test(status);const warn=/pend|agendada|baixo|config/i.test(status);return <span className={`status-badge ${ok?'ok':warn?'warn':'bad'}`}>{status}</span>}
function Metric({icon:Icon,label,value,delta,tone='gold',art}:{icon:any;label:string;value:string;delta:string;tone?:string;art?:string}){return <article className={`metric-card tone-${tone}`}><div className={`metric-icon ${art?'metric-real-icon':''}`}>{art?<img src={art} alt=""/>:<Icon size={20}/>}</div><div className="metric-copy"><small>{label}</small><strong>{value}</strong><span><TrendingUp size={12}/>{delta}</span></div><ArrowUpRight className="metric-arrow" size={16}/></article>}
function BrandIcon({kind}:{kind:string}){const src:Record<string,string>={pix:'https://cdn.simpleicons.org/pix/32BCAD',whatsapp:'https://cdn.simpleicons.org/whatsapp/25D366',ifood:'https://cdn.simpleicons.org/ifood/EA1D2C'};if(src[kind])return <img className="brand-real-icon" src={src[kind]} alt={kind}/>;if(kind==='storefront')return <Store/>;if(kind==='pdv')return <ShoppingCart/>;if(kind==='stock')return <Boxes/>;return <QrCode/>}
function MiniLine({data}:{data:{date:string;revenue:number}[]}){const max=Math.max(1,...data.map(d=>d.revenue));const w=720,h=190,p=18;const pts=data.map((d,i)=>`${p+i*((w-p*2)/Math.max(1,data.length-1))},${h-p-(d.revenue/max)*(h-p*2)}`).join(' ');return <div className="line-chart"><svg viewBox={`0 0 ${w} ${h}`} preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#f6bd4c" stopOpacity=".32"/><stop offset="1" stopColor="#f6bd4c" stopOpacity="0"/></linearGradient></defs><g className="grid-lines"><line x1="0" y1="40" x2={w} y2="40"/><line x1="0" y1="95" x2={w} y2="95"/><line x1="0" y1="150" x2={w} y2="150"/></g><polygon fill="url(#area)" points={`${p},${h-p} ${pts} ${w-p},${h-p}`}/><polyline points={pts} fill="none" stroke="#f6bd4c" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/>{data.map((d,i)=>{const [x,y]=pts.split(' ')[i].split(',');return <circle key={d.date} cx={x} cy={y} r="4" fill="#090a0c" stroke="#ffd36a" strokeWidth="3"/>})}</svg><div className="chart-axis">{data.map(d=><span key={d.date}>{new Date(`${d.date}T12:00:00`).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})}</span>)}</div></div>}
function Donut({rows}:{rows:{channel:string;revenue:number}[]}){const total=rows.reduce((a,b)=>a+Number(b.revenue),0)||1;let cur=0;const colors=['#f4b93f','#24c96b','#4d8eff','#8d4de8','#ea4a61'];const stops=rows.map((r,i)=>{const a=cur;cur+=Number(r.revenue)/total*100;return `${colors[i%colors.length]} ${a}% ${cur}%`}).join(', ');return <div className="donut-wrap"><div className="donut" style={{background:`conic-gradient(${stops||'#2a2a2d 0 100%'})`}}><div><strong>{money(total)}</strong><span>Total</span></div></div><div className="donut-legend">{rows.slice(0,5).map((r,i)=><div key={r.channel}><i style={{background:colors[i%colors.length]}}/><span>{channelName(r.channel)}</span><b>{money(r.revenue)}</b><em>{Math.round(Number(r.revenue)/total*100)}%</em></div>)}</div></div>}

export default function ManagerApp(){
  const appRef=useRef<HTMLDivElement|null>(null);
  const [view,setView]=useState<View>('dashboard');
  const [mobileNav,setMobileNav]=useState(false);
  const [toast,setToast]=useState('');
  const [online,setOnline]=useState(false);
  const [dashboard,setDashboard]=useState<Dashboard|null>(null);
  const [products,setProducts]=useState<Product[]>([]);
  const [orders,setOrders]=useState<Order[]>([]);
  const [finance,setFinance]=useState<Finance|null>(null);
  const [reports,setReports]=useState<Reports|null>(null);
  const [customers,setCustomers]=useState<Customer[]>([]);
  const [suppliers,setSuppliers]=useState<Supplier[]>([]);
  const [promotions,setPromotions]=useState<Promotion[]>([]);
  const [integrations,setIntegrations]=useState<Integration[]>([]);
  const [settings,setSettings]=useState<SettingsData|null>(null);
  const [audit,setAudit]=useState<any[]>([]);
  const showToast=(s:string)=>{setToast(s);setTimeout(()=>setToast(''),2600)};

  const load=useCallback(async(v:View)=>{
    try{
      if(v==='dashboard'){const [dash,ints]=await Promise.all([api<Dashboard>('/api/dashboard'),api<Integration[]>('/api/integrations')]);setDashboard(dash);setIntegrations(ints);}
      if(['products','stock','pdv'].includes(v))setProducts(await api('/api/products'));
      if(v==='sales')setOrders(await api('/api/orders?limit=100'));
      if(v==='finance')setFinance(await api('/api/finance'));
      if(v==='reports')setReports(await api('/api/reports'));
      if(v==='customers')setCustomers(await api('/api/customers'));
      if(v==='suppliers')setSuppliers(await api('/api/suppliers'));
      if(v==='marketing')setPromotions(await api('/api/promotions'));
      if(v==='integrations')setIntegrations(await api('/api/integrations'));
      if(v==='settings')setSettings(await api('/api/settings'));
      if(v==='help'){setIntegrations(await api('/api/integrations'));setAudit(await api('/api/audit?limit=12'));}
    }catch(e:any){showToast(e.message)}
  },[]);
  useEffect(()=>{load(view);},[view,load]);
  useEffect(()=>{
    const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if(!reduced) anime({targets:'.page-enter > *',opacity:[0,1],translateY:[10,0],delay:anime.stagger(35),duration:420,easing:'easeOutCubic'});
  },[view,dashboard,products.length,orders.length]);
  useEffect(()=>{
    let ws:WebSocket|undefined, timer:any;
    const connect=()=>{try{ws=new WebSocket(wsUrl());ws.onopen=()=>setOnline(true);ws.onmessage=(e)=>{const m=JSON.parse(e.data);if(m.type==='new_order'){showToast(`Nova venda #${m.order_id} · ${money(m.total)}`);if(view==='dashboard')load('dashboard')}if(m.type==='stock_changed'&&['stock','pdv'].includes(view))load(view)};ws.onclose=()=>{setOnline(false);timer=setTimeout(connect,1800)}}catch{setOnline(false)}};connect();return()=>{clearTimeout(timer);ws?.close()};
  },[view,load]);

  const onPointerMove=(e:React.PointerEvent<HTMLDivElement>)=>{const el=appRef.current;if(!el)return;const r=el.getBoundingClientRect();el.style.setProperty('--manager-x',`${e.clientX-r.left}px`);el.style.setProperty('--manager-y',`${e.clientY-r.top}px`)};

  return <div ref={appRef} onPointerMove={onPointerMove} className={`manager-app manager-premium ${view==='dashboard'?'dashboard-mode':''}`}><div className="manager-pointer-glow"/>
    <aside className={`manager-sidebar ${mobileNav?'open':''}`}>
      <div className="manager-brand"><div className="brand-bottle"><span/></div><div><strong>ADEGA</strong><small>CRM</small></div><button className="mobile-close" onClick={()=>setMobileNav(false)}><X/></button></div>
      <div className="manager-user"><div className="avatar manager-avatar-photo"><img src="data:image/jpeg;base64," alt="Administrador"/></div><div><b>Administrador</b><span>Olá, Diego!</span></div><em>ADMIN</em></div>
      <nav>{nav.map(([id,label,Icon])=><button key={id} className={view===id?'active':''} onClick={()=>{setView(id);setMobileNav(false)}}><Icon size={18}/><span>{label}</span>{id==='integrations'&&<em>NOVO</em>}</button>)}</nav>
      <div className="manager-plan"><Sparkles size={18}/><div><b>Plano Profissional</b><span>Gestão + Vitrine + PDV</span></div><div className="plan-bar"><i/></div></div>
      <div className="manager-company"><span>Adega Exemplo LTDA</span><small>CNPJ 12.345.678/0001-90</small></div>
    </aside>
    <div className={`nav-scrim ${mobileNav?'show':''}`} onClick={()=>setMobileNav(false)}/>
    <main className="manager-stage">
      <header className="manager-topbar dashboard-blueprint-topbar"><div className="top-title"><button className="mobile-menu" onClick={()=>setMobileNav(true)}><Menu/></button><div><h1>{meta[view][0]}</h1><p>{meta[view][1]}</p></div></div><div className="top-right"><div className="today-chip blueprint-date"><span>{new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'long'}).format(new Date()).replace(' de ',' de ')}</span><Clock3 size={17}/></div><button className="round-action blueprint-bell" aria-label="Notificações"><Bell size={18}/><i/><em>8</em></button><button className="round-action blueprint-help" aria-label="Ajuda" onClick={()=>setView('help')}><CircleHelp size={18}/></button><Link href="/vitrine" target="_blank" className="round-action blueprint-exit" aria-label="Abrir vitrine"><ExternalLink size={18}/></Link><button className="round-action logout-action" title="Sair" onClick={async()=>{try{await api('/api/auth/logout',{method:'POST'})}finally{window.location.href='/login'}}}><LogOut size={18}/></button></div></header>
      <section className="manager-content page-enter">
        {view==='dashboard'&&<DashboardView data={dashboard} integrations={integrations} online={online} onNavigate={setView}/>} {view==='sales'&&<SalesView orders={orders}/>} {view==='pdv'&&<PDV products={products} onDone={()=>{load('pdv');showToast('Venda concluída e estoque atualizado')}}/>}
        {view==='products'&&<ProductsView products={products} reload={()=>load('products')} toast={showToast}/>} {view==='stock'&&<StockView products={products} reload={()=>load('stock')} toast={showToast}/>} {view==='customers'&&<CustomersView rows={customers} reload={()=>load('customers')} toast={showToast}/>} {view==='suppliers'&&<SuppliersView rows={suppliers} reload={()=>load('suppliers')} toast={showToast}/>} {view==='finance'&&<FinanceView data={finance} reload={()=>load('finance')} toast={showToast}/>} {view==='reports'&&<ReportsView data={reports}/>} {view==='marketing'&&<MarketingView rows={promotions} reload={()=>load('marketing')} toast={showToast}/>} {view==='integrations'&&<IntegrationsView rows={integrations}/>} {view==='settings'&&<SettingsView data={settings} reload={()=>load('settings')} toast={showToast}/>} {view==='help'&&<HelpView integrations={integrations} audit={audit} online={online}/>} 
      </section>
    </main><Toast text={toast}/>
  </div>
}

function DashboardView({data,integrations,online,onNavigate}:{data:Dashboard|null;integrations:Integration[];online:boolean;onNavigate:(v:View)=>void}){
  if(!data)return <Loading/>;
  const quick=[
    [ShoppingCart,'Nova Venda','(PDV)','pdv'],[QrCode,'Cobrar PIX','', 'pdv'],[Package,'Adicionar','Produto','products'],
    [Warehouse,'Entrada de','Estoque','stock'],[Users,'Novo Cliente','', 'customers'],[BarChart3,'Ver Relatórios','', 'reports']
  ] as const;
  const feed=[
    ...data.recent.slice(0,4).map(o=>({key:`order-${o.id}`,kind:o.channel,title:o.channel==='ifood'?'Nova venda no iFood':o.channel==='storefront'?'Venda na vitrine':o.channel==='pdv'?'Venda no balcão':'PIX aprovado',detail:`Pedido #${o.id} • ${money(o.total)}`,time:new Date(o.created_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})})),
    ...(data.low_stock[0]?[{key:'stock',kind:'stock',title:'Entrada de estoque',detail:`${data.low_stock[0].stock} unidades • ${data.low_stock[0].name}`,time:'11:40'}]:[])
  ].slice(0,5);
  const iconFor=(kind:string)=><BrandIcon kind={kind}/>;
  const receipt=data.revenue;
  const expenses=Math.max(0,data.gross_profit-data.net_result);
  const cash=Math.max(0,data.net_result*.57);
  const paymentTotal=data.payments.reduce((n,p)=>n+p.revenue,0)||1;
  return <div className="dashboard-blueprint">
    <section className="dashboard-core">
      <div className="metrics-grid dashboard-kpis">
        <Metric icon={CircleDollarSign} art="https://img.icons8.com/3d-fluency/94/money-bag.png" label="Faturamento hoje" value={money(data.revenue)} delta="18,6% vs ontem"/>
        <Metric icon={ShoppingCart} art="https://img.icons8.com/3d-fluency/94/shopping-cart.png" label="Vendas hoje" value={`${data.sales} pedidos`} delta="12,4% vs ontem" tone="green"/>
        <Metric icon={ReceiptText} art="https://img.icons8.com/3d-fluency/94/receipt.png" label="Ticket médio" value={money(data.ticket)} delta="6,3% vs ontem" tone="blue"/>
        <Metric icon={CircleDollarSign} art="https://img.icons8.com/3d-fluency/94/coins.png" label="Lucro bruto (hoje)" value={money(data.gross_profit)} delta="15,7% vs ontem" tone="purple"/>
        <Metric icon={Tag} art="https://img.icons8.com/3d-fluency/94/price-tag.png" label="Produtos vendidos" value={`${data.units} un.`} delta="11,9% vs ontem" tone="amber"/>
      </div>

      <div className="dashboard-main-grid dashboard-chart-row">
        <article className="panel donut-panel blueprint-panel"><PanelHead title="Faturamento por canal" action="Hoje"/><Donut rows={data.channels}/></article>
        <article className="panel revenue-panel blueprint-panel"><PanelHead title="Evolução do faturamento" action="7 dias"/><MiniLine data={data.daily_revenue}/></article>
      </div>

      <div className="dashboard-bottom-grid dashboard-detail-row">
        <article className="panel blueprint-panel recent-sales"><PanelHead title="Vendas recentes" action="Ver todas"/><div className="table-labels"><span>Pedido</span><span>Canal</span><span>Valor</span><span>Horário</span><span>Status</span></div><div className="compact-table">{data.recent.length?data.recent.slice(0,5).map(o=><div className="table-row" key={o.id}><span>#{o.id}</span><b>{channelName(o.channel)}</b><strong>{money(o.total)}</strong><small>{new Date(o.created_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small><StatusBadge status={o.status}/></div>):<Empty/>}</div></article>
        <article className="panel blueprint-panel top-products"><PanelHead title="Produtos mais vendidos" action="Ver todos"/><div className="rank-list">{data.top_products.slice(0,5).map((p,i)=><div key={p.name}><ProductArt name={p.name} category="" className="mini-product-art"/><b>{p.name}</b><em>{p.qty} un.</em></div>)}</div></article>
        <article className="panel blueprint-panel stock-alerts"><PanelHead title="Estoque — alertas" action="Ver todos"/><div className="alert-list">{data.low_stock.length?data.low_stock.slice(0,5).map(p=><div key={p.id} className={p.stock<=p.min_stock/2?'critical':''}><TriangleAlert size={16}/><div><b>{p.name}</b><span>{p.stock<=0?'Sem estoque':p.stock<=p.min_stock/2?'Estoque crítico':'Estoque baixo'}</span></div><strong>{p.stock} un.</strong></div>):<div className="all-good"><CheckCircle2/>Estoque saudável</div>}</div></article>
      </div>

      <section className="finance-ribbon blueprint-finance">
        <div className="finance-summary-title">RESUMO FINANCEIRO</div>
        <div className="finance-summary-grid">
          <div><small>RECEBIMENTOS (HOJE)</small><strong>{money(receipt)}</strong></div>
          <div className="expense"><small>DESPESAS (HOJE)</small><strong>{money(expenses)}</strong></div>
          <div><small>LUCRO LÍQUIDO (HOJE)</small><strong>{money(data.net_result)}</strong></div>
          <div className="cash"><small>SALDO NO CAIXA</small><strong>{money(cash)}</strong></div>
        </div>
        <div className="payments-blueprint"><h4>FORMAS DE PAGAMENTO (HOJE)</h4>{data.payments.slice(0,3).map((p,i)=>{const pct=Math.round(p.revenue/paymentTotal*100);return <div key={p.payment_method}><span>{payName(p.payment_method)}</span><i><b style={{width:`${pct}%`}}/></i><strong>{money(p.revenue)}</strong><em>{pct}%</em></div>})}</div>
      </section>
    </section>

    <aside className="dashboard-side-rail">
      <article className="panel blueprint-panel quick-actions-panel"><PanelHead title="Ações rápidas"/><div className="quick-action-grid">{quick.map(([Icon,a,b,target])=><button key={a+b} onClick={()=>onNavigate(target)}><Icon/><span>{a}{b&&<><br/>{b}</>}</span></button>)}</div></article>
      <article className="panel blueprint-panel activity-panel"><PanelHead title="Feed de atividades" action="Ver todas"/><div className="activity-list">{feed.map(x=><div key={x.key}><div className={`activity-icon ${x.kind}`}>{iconFor(x.kind)}</div><div><b>{x.title}</b><span>{x.detail}</span></div><time>{x.time}</time></div>)}</div></article>
      <article className="panel blueprint-panel integrations-panel"><PanelHead title="Integrações" action="Ver todas"/><div className="dashboard-integration-list">{(integrations.length?integrations:[{slug:'ifood',name:'iFood',status:'ready'},{slug:'storefront',name:'Vitrine própria',status:'ready'},{slug:'whatsapp',name:'WhatsApp Business',status:'ready'},{slug:'pix',name:'PIX (Maquininha)',status:'ready'}] as Integration[]).slice(0,4).map(i=><div key={i.slug}><span className={`integration-mini-logo ${i.slug}`}><BrandIcon kind={i.slug}/></span><b>{i.name}</b><em>{i.status==='ready'?'Conectado':'Configurar'}</em></div>)}</div></article>
    </aside>

    <footer className="dashboard-statusbar"><span className={online?'online':''}><i/> {online?'Sistema online':'Reconectando'}</span><b>Dados atualizados em tempo real</b><em>Versão 2.5.0 <RefreshCw size={14}/></em></footer>
  </div>
}
function PanelHead({title,action}:{title:string;action?:string}){return <div className="panel-head"><h3>{title}</h3>{action&&<button>{action}<ChevronRight size={13}/></button>}</div>}
function Loading(){return <div className="loading-grid">{Array.from({length:8}).map((_,i)=><i key={i}/>)}</div>}

function SalesView({orders}:{orders:Order[]}){const [q,setQ]=useState('');const rows=orders.filter(o=>!q||String(o.id).includes(q)||channelName(o.channel).toLowerCase().includes(q.toLowerCase()));return <article className="panel data-panel"><div className="toolbar"><div className="search-field"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar por pedido ou canal..."/></div><div className="filter-actions"><button><SlidersHorizontal/>Filtros</button><button className="primary-small">Exportar</button></div></div><div className="data-table"><div className="data-head"><span>ID</span><span>Data</span><span>Canal</span><span>Pagamento</span><span>Total</span><span>Status</span></div>{rows.map(o=><div className="data-row" key={o.id}><span>#{o.id}</span><span>{dateTime(o.created_at)}</span><b>{channelName(o.channel)}</b><span>{payName(o.payment_method)}</span><strong>{money(o.total)}</strong><StatusBadge status={o.status}/></div>)}</div>{!rows.length&&<Empty/>}</article>}

function PDV({products,onDone}:{products:Product[];onDone:()=>void}){const [q,setQ]=useState('');const [cart,setCart]=useState<Record<number,number>>({});const [method,setMethod]=useState('pix');const list=products.filter(p=>p.stock>0&&(!q||`${p.name} ${p.category}`.toLowerCase().includes(q.toLowerCase())));const items=Object.entries(cart).map(([id,qty])=>({p:products.find(p=>p.id===+id)!,qty})).filter(x=>x.p);const total=items.reduce((s,x)=>s+x.p.price*x.qty,0);const add=(id:number,d=1)=>setCart(c=>{const p=products.find(x=>x.id===id);const n=Math.max(0,Math.min(p?.stock||0,(c[id]||0)+d));const v={...c};if(n)v[id]=n;else delete v[id];return v});const checkout=async()=>{if(!items.length)return;await api('/api/orders',{method:'POST',body:JSON.stringify({channel:'pdv',payment_method:method,items:items.map(x=>({product_id:x.p.id,qty:x.qty})),discount:0})});setCart({});onDone()};return <div className="pdv-layout"><article className="panel pdv-products"><div className="pdv-search"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar produtos, categorias ou código..."/><button><ScanIcon/></button></div><div className="category-chips"><button className="active">Todos</button>{[...new Set(products.map(p=>p.category))].slice(0,5).map(c=><button key={c}>{c}</button>)}</div><div className="pdv-grid">{list.map(p=><button className="pdv-product" key={p.id} onClick={()=>add(p.id)}><ProductArt name={p.name} category={p.category} image={p.image_url}/><div><small>{p.category}{p.volume_ml?` · ${p.volume_ml} ml`:''}</small><b>{p.name}</b><strong>{money(p.price)}</strong><em>{p.stock} un.</em></div><span><Plus/></span></button>)}</div></article><aside className="panel pdv-cart"><div className="cart-title"><div><small>VENDA ATUAL</small><h3>Itens da venda</h3></div><span>{items.reduce((s,x)=>s+x.qty,0)} itens</span></div><div className="pdv-cart-list">{items.length?items.map(x=><div key={x.p.id}><ProductArt name={x.p.name} category={x.p.category} image={x.p.image_url}/><div><b>{x.p.name}</b><small>{money(x.p.price)} cada</small><div className="qty-control"><button onClick={()=>add(x.p.id,-1)}><Minus/></button><span>{x.qty}</span><button onClick={()=>add(x.p.id,1)}><Plus/></button></div></div><strong>{money(x.p.price*x.qty)}</strong><button className="remove" onClick={()=>setCart(c=>{const n={...c};delete n[x.p.id];return n})}><Trash2/></button></div>):<Empty>Adicione produtos para iniciar a venda.</Empty>}</div><div className="pdv-summary"><div><span>Subtotal</span><b>{money(total)}</b></div><div><span>Desconto</span><b>{money(0)}</b></div><div className="total"><span>Total</span><strong>{money(total)}</strong></div></div><div className="payment-grid"><button className={method==='pix'?'active pix':''} onClick={()=>setMethod('pix')}><QrCode/>PIX</button><button className={method==='card'?'active card':''} onClick={()=>setMethod('card')}><CreditCard/>Cartão</button><button className={method==='cash'?'active cash':''} onClick={()=>setMethod('cash')}><Banknote/>Dinheiro</button></div><button className="finish-sale" disabled={!items.length} onClick={checkout}>FINALIZAR VENDA <ChevronRight/></button></aside></div>}
function ScanIcon(){return <span style={{fontWeight:800}}>▥</span>}

function ProductsView({products,reload,toast}:{products:Product[];reload:()=>void;toast:(s:string)=>void}){
  const [open,setOpen]=useState(false);
  const [catalogOpen,setCatalogOpen]=useState(false);
  const [catalogQuery,setCatalogQuery]=useState('');
  const [form,setForm]=useState({name:'',category:'Cervejas',sku:'',cost:'0',price:'0',stock:'0',min_stock:'5',volume_ml:'',image_url:''});
  const choose=(item:BeverageCatalogItem)=>{setForm({...form,name:item.name,category:item.category,sku:item.sku,volume_ml:String(item.volumeMl),image_url:item.image});setCatalogOpen(false)};
  const save=async()=>{try{await api('/api/products',{method:'POST',body:JSON.stringify({...form,cost:+form.cost,price:+form.price,stock:+form.stock,min_stock:+form.min_stock,volume_ml:+form.volume_ml||null,storefront:true})});setOpen(false);reload();toast('Produto cadastrado')}catch(e:any){toast(e.message)}};
  const catalog=beverageCatalog.filter(x=>!catalogQuery||`${x.name} ${x.category} ${x.volumeMl}`.toLowerCase().includes(catalogQuery.toLowerCase()));
  return <>
    <article className="panel data-panel"><div className="toolbar"><div className="search-field"><Search/><input placeholder="Buscar produto..."/></div><button className="primary-small" onClick={()=>setOpen(true)}><Plus/>Novo produto</button></div><div className="product-table"><div className="product-head"><span>Produto</span><span>Categoria</span><span>Custo</span><span>Preço</span><span>Estoque</span><span>Status</span></div>{products.map(p=><div className="product-row" key={p.id}><div className="product-name"><ProductArt name={p.name} category={p.category} image={p.image_url}/><div><b>{p.name}</b><small>{p.volume_ml?`${p.volume_ml} ml · `:''}{p.sku||'Sem SKU'}</small></div></div><span>{p.category}</span><span>{money(p.cost)}</span><strong>{money(p.price)}</strong><span>{p.stock} un.</span><StatusBadge status={p.stock<=0?'Sem estoque':p.stock<=p.min_stock?'Baixo':'Normal'}/></div>)}</div></article>
    {open&&<Modal title="Novo produto" onClose={()=>setOpen(false)}><button className="catalog-picker-button" onClick={()=>setCatalogOpen(true)}><span><Sparkles/>Selecionar na base de bebidas</span><small>Fotos, categoria e volume preenchidos automaticamente</small><ChevronRight/></button>{form.image_url&&<div className="selected-beverage"><ProductArt name={form.name} category={form.category} image={form.image_url}/><div><b>{form.name}</b><span>{form.category} · {form.volume_ml} ml</span></div></div>}<div className="form-grid"><label className="wide">Nome<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Categoria<input value={form.category} onChange={e=>setForm({...form,category:e.target.value})}/></label><label>Volume (ml)<input type="number" value={form.volume_ml} onChange={e=>setForm({...form,volume_ml:e.target.value})}/></label><label>SKU<input value={form.sku} onChange={e=>setForm({...form,sku:e.target.value})}/></label><label>Custo<input type="number" value={form.cost} onChange={e=>setForm({...form,cost:e.target.value})}/></label><label>Preço<input type="number" value={form.price} onChange={e=>setForm({...form,price:e.target.value})}/></label><label>Estoque<input type="number" value={form.stock} onChange={e=>setForm({...form,stock:e.target.value})}/></label><label>Mínimo<input type="number" value={form.min_stock} onChange={e=>setForm({...form,min_stock:e.target.value})}/></label><button className="modal-primary wide" onClick={save}>Cadastrar produto</button></div></Modal>}
    {catalogOpen&&<div className="catalog-layer"><div className="modal-backdrop" onClick={()=>setCatalogOpen(false)}/><section className="catalog-card"><div className="catalog-head"><div><small>BASE ADEGA CRM</small><h3>Selecione uma bebida</h3></div><button onClick={()=>setCatalogOpen(false)}><X/></button></div><div className="catalog-search"><Search/><input autoFocus value={catalogQuery} onChange={e=>setCatalogQuery(e.target.value)} placeholder="Buscar whisky, cerveja, vodka, volume..."/></div><div className="beverage-catalog-grid">{catalog.map(item=><button key={item.sku} onClick={()=>choose(item)}><ProductArt name={item.name} category={item.category} image={item.image}/><div><small>{item.category}</small><b>{item.name}</b><span>{item.volumeMl} ml</span></div><Plus/></button>)}</div></section></div>}
  </>;
}

function StockView({products,reload,toast}:{products:Product[];reload:()=>void;toast:(s:string)=>void}){
  const [catalogOpen,setCatalogOpen]=useState(false),[query,setQuery]=useState(''),[selected,setSelected]=useState<BeverageCatalogItem|null>(null);
  const [entry,setEntry]=useState({cost:'0',price:'0',stock:'1',min_stock:'5'});
  const total=products.reduce((a,p)=>a+p.cost*p.stock,0),critical=products.filter(p=>p.stock<=p.min_stock).length;
  const adjust=async(p:Product,delta:number)=>{try{await api(`/api/products/${p.id}/stock`,{method:'POST',body:JSON.stringify({delta,reason:delta>0?'Entrada manual':'Saída manual'})});reload();toast('Estoque atualizado')}catch(e:any){toast(e.message)}};
  const addFromBase=async()=>{if(!selected)return;try{await api('/api/products',{method:'POST',body:JSON.stringify({name:selected.name,category:selected.category,sku:selected.sku,cost:+entry.cost,price:+entry.price,stock:+entry.stock,min_stock:+entry.min_stock,volume_ml:selected.volumeMl,image_url:selected.image,storefront:true})});setCatalogOpen(false);setSelected(null);reload();toast('Bebida adicionada ao estoque')}catch(e:any){toast(e.message)}};
  const catalog=beverageCatalog.filter(x=>!query||`${x.name} ${x.category} ${x.volumeMl}`.toLowerCase().includes(query.toLowerCase()));
  return <><div className="stock-metrics"><Metric icon={Boxes} label="Valor total em estoque" value={money(total)} delta={`${products.length} produtos`} tone="green"/><Metric icon={TriangleAlert} label="Abaixo do mínimo" value={`${critical}`} delta="Exige atenção" tone="amber"/><Metric icon={Package} label="Sem estoque" value={`${products.filter(p=>p.stock<=0).length}`} delta="Reposição necessária" tone="purple"/></div><article className="panel data-panel"><div className="stock-toolbar"><div><h3>Produtos em estoque</h3><span>Fotos e volumes integrados à base</span></div><button className="primary-small" onClick={()=>setCatalogOpen(true)}><Plus/>Adicionar da base</button></div><div className="data-table stock-data"><div className="data-head"><span>Produto</span><span>Atual</span><span>Mínimo</span><span>Status</span><span>Movimentar</span><span>Ações</span></div>{products.map(p=><div className="data-row" key={p.id}><div className="stock-product-cell"><ProductArt name={p.name} category={p.category} image={p.image_url}/><span><b>{p.name}</b><small>{p.volume_ml?`${p.volume_ml} ml · `:''}{p.category}</small></span></div><strong>{p.stock} un.</strong><span>{p.min_stock} un.</span><StatusBadge status={p.stock<=0?'Sem estoque':p.stock<=p.min_stock?'Baixo':'Normal'}/><div className="inline-adjust"><button onClick={()=>adjust(p,-1)}><Minus/></button><button onClick={()=>adjust(p,1)}><Plus/></button></div><button className="ghost-inline">Histórico</button></div>)}</div></article>{catalogOpen&&<div className="catalog-layer"><div className="modal-backdrop" onClick={()=>setCatalogOpen(false)}/><section className="catalog-card"><div className="catalog-head"><div><small>ESTOQUE · BASE ADEGA CRM</small><h3>{selected?'Complete a entrada':'Selecione uma bebida'}</h3></div><button onClick={()=>{setCatalogOpen(false);setSelected(null)}}><X/></button></div>{selected?<div className="stock-catalog-entry"><div className="selected-stock-drink"><ProductArt name={selected.name} category={selected.category} image={selected.image}/><div><small>{selected.category}</small><h4>{selected.name}</h4><strong>{selected.volumeMl} ml</strong></div></div><div className="form-grid"><label>Custo<input type="number" value={entry.cost} onChange={e=>setEntry({...entry,cost:e.target.value})}/></label><label>Preço<input type="number" value={entry.price} onChange={e=>setEntry({...entry,price:e.target.value})}/></label><label>Quantidade<input type="number" value={entry.stock} onChange={e=>setEntry({...entry,stock:e.target.value})}/></label><label>Estoque mínimo<input type="number" value={entry.min_stock} onChange={e=>setEntry({...entry,min_stock:e.target.value})}/></label><button className="ghost-inline" onClick={()=>setSelected(null)}>Voltar à base</button><button className="modal-primary" onClick={addFromBase}>Adicionar ao estoque</button></div></div>:<><div className="catalog-search"><Search/><input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar por nome, categoria ou ml..."/></div><div className="beverage-catalog-grid">{catalog.map(item=><button key={item.sku} onClick={()=>setSelected(item)}><ProductArt name={item.name} category={item.category} image={item.image}/><div><small>{item.category}</small><b>{item.name}</b><span>{item.volumeMl} ml</span></div><Plus/></button>)}</div></>}</section></div>}</>;
}

function CustomersView({rows}:{rows:Customer[];reload:()=>void;toast:(s:string)=>void}){const total=rows[0];return <div className="split-layout"><article className="panel data-panel"><PanelHead title="Clientes — modo privacidade" action="Zero retenção de PII"/><div className="people-list"><div><div className="person-avatar">AN</div><div><b>Compras anônimas</b><small>Nomes, telefones, e-mails e endereços não são armazenados</small></div><span>{total?.orders||0} pedidos</span><strong>{money(total?.spent||0)}</strong></div></div></article><aside className="panel side-form"><h3>Privacidade por padrão</h3><p>O CRM mantém apenas métricas de vendas. Dados necessários para entrega são usados somente durante o checkout e encaminhados ao canal operacional, sem retenção no banco da Adega CRM.</p><div className="security-note">LGPD · minimização · zero-data retention para clientes</div></aside></div>}
function SuppliersView({rows,reload,toast}:{rows:Supplier[];reload:()=>void;toast:(s:string)=>void}){const [f,setF]=useState({name:'',contact:'',phone:''});const add=async()=>{if(!f.name)return;await api('/api/suppliers',{method:'POST',body:JSON.stringify(f)});setF({name:'',contact:'',phone:''});reload();toast('Fornecedor adicionado')};return <div className="split-layout"><article className="panel data-panel"><PanelHead title="Fornecedores" action={`${rows.length} cadastrados`}/><div className="supplier-grid">{rows.map(s=><article key={s.id}><Truck/><div><b>{s.name}</b><span>{s.contact||'Contato comercial'}</span><small>{s.phone||'Sem telefone'}</small></div><ChevronRight/></article>)}</div>{!rows.length&&<Empty/>}</article><aside className="panel side-form"><h3>Novo fornecedor</h3><label>Empresa<input value={f.name} onChange={e=>setF({...f,name:e.target.value})}/></label><label>Contato<input value={f.contact} onChange={e=>setF({...f,contact:e.target.value})}/></label><label>Telefone<input value={f.phone} onChange={e=>setF({...f,phone:e.target.value})}/></label><button onClick={add}>Cadastrar fornecedor</button></aside></div>}

function FinanceView({data,reload,toast}:{data:Finance|null;reload:()=>void;toast:(s:string)=>void}){const [open,setOpen]=useState(false);const [f,setF]=useState({description:'',category:'Operacional',amount:'0'});if(!data)return <Loading/>;const save=async()=>{await api('/api/finance/expenses',{method:'POST',body:JSON.stringify({...f,amount:+f.amount})});setOpen(false);reload();toast('Despesa registrada')};return <><div className="finance-metrics"><Metric icon={TrendingUp} label="Receitas" value={money(data.revenue)} delta="Acumulado" tone="green"/><Metric icon={CircleDollarSign} label="CMV" value={money(data.cogs)} delta="Custo das vendas" tone="amber"/><Metric icon={ReceiptText} label="Despesas" value={money(data.expenses)} delta="Operacional" tone="purple"/><Metric icon={WalletCards} label="Resultado líquido" value={money(data.net)} delta="Após custos e despesas" tone="blue"/></div><div className="finance-layout"><article className="panel"><PanelHead title="Receitas x despesas" action="Acumulado"/><div className="finance-bars"><div><span>Receitas</span><i style={{width:'100%'}}/><b>{money(data.revenue)}</b></div><div><span>CMV</span><i style={{width:`${Math.min(100,data.cogs/(data.revenue||1)*100)}%`}}/><b>{money(data.cogs)}</b></div><div><span>Despesas</span><i style={{width:`${Math.min(100,data.expenses/(data.revenue||1)*100)}%`}}/><b>{money(data.expenses)}</b></div></div></article><article className="panel"><div className="panel-head"><h3>Despesas recentes</h3><button onClick={()=>setOpen(true)}><Plus/>Adicionar</button></div><div className="expense-list">{data.expense_items.slice(0,8).map(e=><div key={e.id}><div><b>{e.description}</b><small>{e.category} · {dateTime(e.created_at)}</small></div><strong>{money(e.amount)}</strong></div>)}</div></article></div>{open&&<Modal title="Registrar despesa" onClose={()=>setOpen(false)}><div className="form-grid"><label className="wide">Descrição<input value={f.description} onChange={e=>setF({...f,description:e.target.value})}/></label><label>Categoria<input value={f.category} onChange={e=>setF({...f,category:e.target.value})}/></label><label>Valor<input type="number" value={f.amount} onChange={e=>setF({...f,amount:e.target.value})}/></label><button className="modal-primary wide" onClick={save}>Salvar despesa</button></div></Modal>}</>}
function ReportsView({data}:{data:Reports|null}){const [tab,setTab]=useState('period');if(!data)return <Loading/>;const s=data.summary;return <div className="reports-layout"><aside className="panel report-nav"><h3>Relatórios</h3>{[['period','Vendas por período'],['profit','Lucro por produto'],['channel','Vendas por canal'],['ticket','Ticket médio'],['stock','Estoque parado'],['dre','DRE simplificada']].map(([id,l])=><button key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}><BarChart3/>{l}</button>)}</aside><section className="report-stage"><div className="report-kpis"><div><small>Faturamento</small><strong>{money(s.revenue)}</strong></div><div><small>Pedidos</small><strong>{s.orders}</strong></div><div><small>Ticket médio</small><strong>{money(s.ticket)}</strong></div><div><small>Itens</small><strong>{s.units}</strong></div></div><article className="panel report-main"><PanelHead title={tab==='dre'?'DRE simplificada':tab==='profit'?'Lucro por produto':tab==='stock'?'Estoque parado':tab==='channel'?'Vendas por canal':tab==='ticket'?'Ticket médio':'Vendas por período'} action="30 dias"/>{tab==='period'&&<MiniLine data={data.daily.map(x=>({date:x.day,revenue:x.revenue}))}/>} {tab==='channel'&&<Donut rows={data.channels}/>} {tab==='dre'&&<div className="dre"><div><span>(+) Receita bruta</span><b>{money(s.revenue)}</b></div><div><span>(−) CMV</span><b>{money(s.cogs)}</b></div><div className="sub"><span>(=) Lucro bruto</span><b>{money(s.gross_profit)}</b></div><div><span>(−) Despesas</span><b>{money(s.expenses)}</b></div><div className="total"><span>(=) Resultado líquido</span><b>{money(s.net)}</b></div></div>} {tab==='profit'&&<SimpleReport rows={data.product_profit.slice(0,12)} columns={['name','qty','revenue','profit']}/>} {tab==='stock'&&<SimpleReport rows={data.stock_turnover.slice(0,12)} columns={['name','stock','sold','min_stock']}/>} {tab==='ticket'&&<div className="big-report-number"><small>Ticket médio acumulado</small><strong>{money(s.ticket)}</strong><span>Baseado em {s.orders} pedidos confirmados</span></div>}</article></section></div>}
function SimpleReport({rows,columns}:{rows:any[];columns:string[]}){return <div className="simple-report">{rows.map((r,i)=><div key={i}>{columns.map(c=><span key={c}>{c==='name'?<b>{r[c]}</b>:typeof r[c]==='number'&&/revenue|profit|cost/.test(c)?money(r[c]):String(r[c]??'—')}</span>)}</div>)}</div>}

function MarketingView({rows,reload,toast}:{rows:Promotion[];reload:()=>void;toast:(s:string)=>void}){const [open,setOpen]=useState(false);const [f,setF]=useState({name:'',type:'Produto',period:'Sem período',status:'Ativa',discount_type:'percent',value:'10'});const save=async()=>{await api('/api/promotions',{method:'POST',body:JSON.stringify({...f,value:+f.value})});setOpen(false);reload();toast('Promoção criada')};const del=async(id:number)=>{await api(`/api/promotions/${id}`,{method:'DELETE'});reload();toast('Promoção removida')};return <><div className="marketing-layout"><article className="panel data-panel"><div className="panel-head"><h3>Promoções e campanhas</h3><button onClick={()=>setOpen(true)}><Plus/>Nova promoção</button></div><div className="promo-list">{rows.map(p=><div key={p.id}><div><b>{p.name}</b><small>{p.type}</small></div><span>{p.period}</span><strong>{p.discount_type==='percent'?`${p.value}%`:money(p.value)}</strong><StatusBadge status={p.status}/><button onClick={()=>del(p.id)}><Trash2/></button></div>)}</div></article><article className="promo-showcase"><div className="promo-glow"/><Tag/><small>PROMOÇÃO EM DESTAQUE</small><h3>{rows[0]?.name||'Sua próxima campanha'}</h3><p>Campanhas sincronizadas com a vitrine e prontas para destacar produtos.</p><strong>{rows[0]?.discount_type==='percent'?`${rows[0]?.value||10}% OFF`:'OFERTA ESPECIAL'}</strong><button>Ver na vitrine <ExternalLink/></button></article></div>{open&&<Modal title="Nova promoção" onClose={()=>setOpen(false)}><div className="form-grid"><label className="wide">Nome<input value={f.name} onChange={e=>setF({...f,name:e.target.value})}/></label><label>Tipo<select value={f.type} onChange={e=>setF({...f,type:e.target.value})}><option>Produto</option><option>Combo</option><option>Cupom</option></select></label><label>Período<input value={f.period} onChange={e=>setF({...f,period:e.target.value})}/></label><label>Desconto<select value={f.discount_type} onChange={e=>setF({...f,discount_type:e.target.value})}><option value="percent">Percentual</option><option value="fixed">Valor fixo</option></select></label><label>Valor<input type="number" value={f.value} onChange={e=>setF({...f,value:e.target.value})}/></label><button className="modal-primary wide" onClick={save}>Criar promoção</button></div></Modal>}</>}
function IntegrationsView({rows}:{rows:Integration[]}){const logos:Record<string,React.ReactNode>={pix:<QrCode/>,ifood:<span className="ifood-logo">iF</span>,whatsapp:<span className="wa-logo">◉</span>,storefront:<Store/>};return <div className="integration-grid">{rows.map(i=><article className={`integration-card ${i.slug}`} key={i.slug}><div className="integration-top"><div>{logos[i.slug]||<PlugZap/>}</div><StatusBadge status={i.status==='ready'?'Conectado':'Não configurado'}/></div><h3>{i.name}</h3><p>{i.note||'Conector preparado para integração oficial.'}</p><div className="integration-foot"><small>Última sincronização</small><b>{i.last_sync?dateTime(i.last_sync):'Aguardando configuração'}</b></div><button>{i.status==='ready'?'Gerenciar':'Configurar'}<ChevronRight/></button></article>)}</div>}
function PasskeySetup({toast}:{toast:(s:string)=>void}){
  const [count,setCount]=useState(0);
  const [busy,setBusy]=useState(false);
  const refresh=useCallback(()=>{api<any>('/api/auth/passkey/status').then(x=>setCount(Number(x.credentials||0))).catch(()=>setCount(0));},[]);
  useEffect(()=>{refresh()},[refresh]);
  const register=async()=>{
    if(!window.PublicKeyCredential){toast('Este navegador não oferece passkeys');return}
    setBusy(true);
    try{
      const platform=await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable();
      if(!platform) throw new Error('Este dispositivo não possui autenticador seguro disponível');
      const options=await api<PasskeyRegisterOptionsJSON>('/api/auth/passkey/register/options',{method:'POST'});
      const credential=await createPlatformPasskey(options);
      await api('/api/auth/passkey/register/verify',{method:'POST',body:JSON.stringify({...credential,label:navigator.platform||'Dispositivo'})});
      toast('Biometria/passkey cadastrada com segurança'); refresh();
    }catch(e:any){toast(e?.name==='NotAllowedError'?'Cadastro biométrico cancelado':(e?.message||'Falha ao cadastrar passkey'))}
    finally{setBusy(false)}
  };
  return <div className="passkey-manage"><div><Fingerprint/><span><b>Biometria / Passkey</b><small>{count?`${count} dispositivo(s) cadastrado(s)`:'Nenhum dispositivo cadastrado'}</small></span></div><button disabled={busy} onClick={register}>{busy?'Aguardando dispositivo…':count?'Cadastrar outro dispositivo':'Cadastrar este dispositivo'}</button></div>
}

function SettingsView({data,reload,toast}:{data:SettingsData|null;reload:()=>void;toast:(s:string)=>void}){const [f,setF]=useState<SettingsData|null>(data);useEffect(()=>setF(data),[data]);if(!f)return <Loading/>;const save=async()=>{await api('/api/settings',{method:'PUT',body:JSON.stringify(f)});reload();toast('Configurações salvas')};return <div className="settings-layout"><article className="panel settings-form"><PanelHead title="Dados da adega" action="Configuração"/><div className="form-grid"><label className="wide">Nome da loja<input value={f.store_name} onChange={e=>setF({...f,store_name:e.target.value})}/></label><label>WhatsApp<input value={f.whatsapp} onChange={e=>setF({...f,whatsapp:e.target.value})}/></label><label>Chave PIX<input value={f.pix_key} onChange={e=>setF({...f,pix_key:e.target.value})}/></label><label>Taxa de entrega<input type="number" value={f.delivery_fee} onChange={e=>setF({...f,delivery_fee:+e.target.value})}/></label><label>Pedido mínimo<input type="number" value={f.minimum_order} onChange={e=>setF({...f,minimum_order:+e.target.value})}/></label><label className="toggle-row wide"><span><b>Vitrine aberta</b><small>Permitir novos pedidos</small></span><input type="checkbox" checked={f.store_open} onChange={e=>setF({...f,store_open:e.target.checked})}/></label><button className="modal-primary wide" onClick={save}>Salvar configurações</button></div></article><article className="security-panel"><ShieldCheck/><small>SEGURANÇA OPERACIONAL</small><h3>Base preparada para operação profissional.</h3><div><span>API FastAPI</span><StatusBadge status="Online"/></div><div><span>Banco SQLite WAL</span><StatusBadge status="Online"/></div><div><span>Auditoria crítica</span><StatusBadge status="Ativa"/></div><div><span>PIX / iFood</span><StatusBadge status="Aguardando configuração"/></div><PasskeySetup toast={toast}/></article></div>}
function HelpView({integrations,audit,online}:{integrations:Integration[];audit:any[];online:boolean}){return <div className="help-layout"><article className="panel"><PanelHead title="Diagnóstico do sistema" action="v1.0 Next"/><div className="diagnostic"><div><b>Frontend Next.js</b><StatusBadge status="Online"/></div><div><b>API FastAPI</b><StatusBadge status="Online"/></div><div><b>Tempo real</b><StatusBadge status={online?'Online':'Reconectando'}/></div>{integrations.map(i=><div key={i.slug}><b>{i.name}</b><StatusBadge status={i.status==='ready'?'Pronto':'Pendente'}/></div>)}</div></article><article className="panel"><PanelHead title="Atividade auditada" action="Últimas ações"/><div className="audit-list">{audit.map(a=><div key={a.id}><div><b>{a.action} · {a.entity}</b><span>{dateTime(a.created_at)}</span></div><small>#{a.entity_id||'—'}</small></div>)}</div></article></div>}
function Modal({title,onClose,children}:{title:string;onClose:()=>void;children?:React.ReactNode}){return <div className="modal-layer"><div className="modal-backdrop" onClick={onClose}/><div className="modal-card"><div className="modal-head"><h3>{title}</h3><button onClick={onClose}><X/></button></div>{children}</div></div>}
